package com.inventoryretexture;

import java.util.Arrays;
import java.util.Collections;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.Silent.class)
public class RetextureStoreTest
{
	private static final int SWORDFISH = 373;
	private static final int SWORDFISH_NOTED = 374;
	private static final int LOBSTER = 379;
	private static final int SHARK = 385;

	@Mock
	private ConfigManager configManager;

	@Mock
	private ItemManager itemManager;

	private RetextureStore store;

	@Before
	public void setUp()
	{
		when(itemManager.canonicalize(anyInt())).thenAnswer(i -> i.getArgument(0));
		when(itemManager.canonicalize(SWORDFISH_NOTED)).thenReturn(SWORDFISH);
		store = new RetextureStore(configManager, itemManager);
	}

	@Test
	public void putStoresCanonicalMappingAndGetResolvesNotedVariant()
	{
		store.put(SWORDFISH_NOTED, LOBSTER);
		verify(configManager).setConfiguration("inventoryretexture", "retexture_" + SWORDFISH, String.valueOf(LOBSTER));
		assertEquals(Integer.valueOf(LOBSTER), store.get(SWORDFISH));
		assertEquals(Integer.valueOf(LOBSTER), store.get(SWORDFISH_NOTED));
	}

	@Test
	public void putSelfClearsMapping()
	{
		store.put(SWORDFISH, LOBSTER);
		store.put(SWORDFISH, SWORDFISH);
		verify(configManager).unsetConfiguration("inventoryretexture", "retexture_" + SWORDFISH);
		assertNull(store.get(SWORDFISH));
	}

	@Test
	public void mappingsResolveExactlyOneHop()
	{
		store.put(SWORDFISH, LOBSTER);
		store.put(LOBSTER, SHARK);
		assertEquals(Integer.valueOf(LOBSTER), store.get(SWORDFISH));
	}

	@Test
	public void removeDeletesKeyAndMapping()
	{
		store.put(SWORDFISH, LOBSTER);
		store.remove(SWORDFISH);
		verify(configManager).unsetConfiguration("inventoryretexture", "retexture_" + SWORDFISH);
		assertNull(store.get(SWORDFISH));
	}

	@Test
	public void loadReadsAllMappingKeys()
	{
		when(configManager.getConfigurationKeys("inventoryretexture.retexture_"))
			.thenReturn(Arrays.asList("inventoryretexture.retexture_" + SWORDFISH));
		when(configManager.getConfiguration("inventoryretexture", "retexture_" + SWORDFISH))
			.thenReturn(String.valueOf(LOBSTER));
		store.load();
		assertEquals(Integer.valueOf(LOBSTER), store.get(SWORDFISH));
	}

	@Test
	public void loadIgnoresMalformedEntries()
	{
		when(configManager.getConfigurationKeys("inventoryretexture.retexture_"))
			.thenReturn(Arrays.asList("inventoryretexture.retexture_notanumber", "inventoryretexture.retexture_" + SWORDFISH));
		when(configManager.getConfiguration("inventoryretexture", "retexture_" + SWORDFISH))
			.thenReturn("junk");
		store.load();
		assertNull(store.get(SWORDFISH));
	}

	@Test
	public void loadClearsPreviousState()
	{
		store.put(SWORDFISH, LOBSTER);
		when(configManager.getConfigurationKeys("inventoryretexture.retexture_"))
			.thenReturn(Collections.emptyList());
		store.load();
		assertNull(store.get(SWORDFISH));
	}
}

package com.inventoryretexture;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.Silent.class)
public class RetextureOverlayTest
{
	private static final int SWORDFISH = 373;
	private static final int LOBSTER = 379;
	private static final Rectangle BOUNDS = new Rectangle(10, 20, 32, 32);

	@Mock
	private ItemManager itemManager;

	@Mock
	private RetextureStore store;

	@Mock
	private InventoryRetextureConfig config;

	@Mock
	private Graphics2D graphics;

	@Mock
	private WidgetItem widgetItem;

	private RetextureOverlay overlay;

	@Before
	public void setUp()
	{
		overlay = new RetextureOverlay(itemManager, store, config);
		when(widgetItem.getCanvasBounds()).thenReturn(BOUNDS);
		when(widgetItem.getQuantity()).thenReturn(1);
		when(config.hideOriginal()).thenReturn(false);
	}

	@Test
	public void drawsOutlineOfTargetItemWhenEnabled()
	{
		final BufferedImage outline = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
		when(store.get(SWORDFISH)).thenReturn(LOBSTER);
		when(config.outlineModified()).thenReturn(true);
		when(config.outlineColor()).thenReturn(Color.CYAN);
		when(itemManager.getItemOutline(LOBSTER, 1, Color.CYAN)).thenReturn(outline);

		overlay.renderItemOverlay(graphics, SWORDFISH, widgetItem);

		verify(graphics).drawImage(outline, BOUNDS.x, BOUNDS.y, null);
	}

	@Test
	public void skipsOutlineWhenDisabled()
	{
		when(store.get(SWORDFISH)).thenReturn(LOBSTER);
		when(config.outlineModified()).thenReturn(false);

		overlay.renderItemOverlay(graphics, SWORDFISH, widgetItem);

		verify(itemManager, never()).getItemOutline(anyInt(), anyInt(), any());
	}

	@Test
	public void skipsOutlineForUnmappedItems()
	{
		when(store.get(SWORDFISH)).thenReturn(null);
		when(config.outlineModified()).thenReturn(true);

		overlay.renderItemOverlay(graphics, SWORDFISH, widgetItem);

		verify(itemManager, never()).getItemOutline(anyInt(), anyInt(), any());
	}
}

