package com.inventoryretexture;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

@Slf4j
@Singleton
class RetextureStore
{
	static final String CONFIG_GROUP = "inventoryretexture";
	static final String KEY_PREFIX = "retexture_";

	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final Map<Integer, Integer> mappings = new ConcurrentHashMap<>();

	@Inject
	RetextureStore(ConfigManager configManager, ItemManager itemManager)
	{
		this.configManager = configManager;
		this.itemManager = itemManager;
	}

	void load()
	{
		mappings.clear();
		final String fullPrefix = CONFIG_GROUP + "." + KEY_PREFIX;
		for (String key : configManager.getConfigurationKeys(fullPrefix))
		{
			final String shortKey = key.substring(CONFIG_GROUP.length() + 1);
			final String value = configManager.getConfiguration(CONFIG_GROUP, shortKey);
			try
			{
				final int source = Integer.parseInt(shortKey.substring(KEY_PREFIX.length()));
				final int target = Integer.parseInt(value);
				mappings.put(source, target);
			}
			catch (NumberFormatException e)
			{
				log.warn("Ignoring malformed re-texture config entry {} = {}", key, value);
			}
		}
	}

	Integer get(int itemId)
	{
		return mappings.get(itemManager.canonicalize(itemId));
	}

	void put(int sourceItemId, int targetItemId)
	{
		final int source = itemManager.canonicalize(sourceItemId);
		final int target = itemManager.canonicalize(targetItemId);
		if (source == target)
		{
			remove(source);
			return;
		}
		mappings.put(source, target);
		configManager.setConfiguration(CONFIG_GROUP, KEY_PREFIX + source, String.valueOf(target));
	}

	void remove(int sourceItemId)
	{
		final int source = itemManager.canonicalize(sourceItemId);
		mappings.remove(source);
		configManager.unsetConfiguration(CONFIG_GROUP, KEY_PREFIX + source);
	}

	void clear()
	{
		mappings.clear();
	}
}

package com.inventoryretexture;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("inventoryretexture")
public interface InventoryRetextureConfig extends Config
{
	@ConfigItem(
		keyName = "hideOriginal",
		name = "Hide original sprite",
		description = "Makes the original item fully transparent under the replacement icon. Turn off if item slots render oddly."
	)
	default boolean hideOriginal()
	{
		return true;
	}

	@ConfigItem(
		keyName = "outlineModified",
		name = "Outline re-textured items",
		description = "Draws an outline on re-textured icons as a reminder that the item shown is not the real one."
	)
	default boolean outlineModified()
	{
		return false;
	}

	@Alpha
	@ConfigItem(
		keyName = "outlineColor",
		name = "Outline color",
		description = "Color of the outline drawn on re-textured items."
	)
	default Color outlineColor()
	{
		return Color.CYAN;
	}
}

package com.inventoryretexture;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.chatbox.ChatboxItemSearch;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Inventory ReTexture",
	description = "Re-map inventory item icons to another item's icon",
	tags = {"inventory", "icon", "texture", "remap", "visual"}
)
public class InventoryRetexturePlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatboxItemSearch itemSearch;

	@Inject
	private RetextureOverlay overlay;

	@Inject
	private RetextureStore store;

	@Provides
	InventoryRetextureConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(InventoryRetextureConfig.class);
	}

	@Override
	protected void startUp()
	{
		store.load();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clientThread.invoke(overlay::restoreHiddenSlots);
		store.clear();
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}

		final MenuEntry[] entries = event.getMenuEntries();
		for (int idx = entries.length - 1; idx >= 0; --idx)
		{
			final MenuEntry entry = entries[idx];
			final Widget w = entry.getWidget();
			if (w != null && WidgetUtil.componentToInterface(w.getId()) == InterfaceID.INVENTORY
				&& "Examine".equals(entry.getOption()) && entry.getIdentifier() == 10)
			{
				final int itemId = w.getItemId();

				if (store.get(itemId) != null)
				{
					client.getMenu().createMenuEntry(idx)
						.setOption("Clear re-texture")
						.setTarget(entry.getTarget())
						.setType(MenuAction.RUNELITE)
						.onClick(e -> store.remove(itemId));
				}

				client.getMenu().createMenuEntry(idx)
					.setOption("Re-texture")
					.setTarget(entry.getTarget())
					.setType(MenuAction.RUNELITE)
					.onClick(e -> openTargetSearch(itemId));
			}
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		store.load();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (RetextureStore.CONFIG_GROUP.equals(event.getGroup()))
		{
			store.load();
		}
	}

	private void openTargetSearch(int sourceItemId)
	{
		final int canonical = itemManager.canonicalize(sourceItemId);
		final String name = itemManager.getItemComposition(canonical).getName();
		itemSearch
			.tooltipText("Re-texture " + name + " as")
			.onItemSelected(targetId ->
				clientThread.invoke(() -> store.put(canonical, targetId)))
			.build();
	}
}

package com.inventoryretexture;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

@Singleton
class RetextureOverlay extends WidgetItemOverlay
{
	private static final int OPACITY_HIDDEN = 255;
	private static final int OPACITY_VISIBLE = 0;

	private final ItemManager itemManager;
	private final RetextureStore store;
	private final InventoryRetextureConfig config;

	// Client-thread-confined: touched only from render and from shutdown via clientThread.invoke.
	private final Set<Widget> hiddenSlots = Collections.newSetFromMap(new IdentityHashMap<>());

	@Inject
	RetextureOverlay(ItemManager itemManager, RetextureStore store, InventoryRetextureConfig config)
	{
		this.itemManager = itemManager;
		this.store = store;
		this.config = config;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		final Widget slot = widgetItem.getWidget();
		final Integer target = store.get(itemId);
		if (target == null)
		{
			// Self-heal: restore a slot we previously hid whose mapping was removed.
			if (slot != null && hiddenSlots.remove(slot))
			{
				slot.setOpacity(OPACITY_VISIBLE);
			}
			return;
		}

		final Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}

		if (config.hideOriginal() && slot != null)
		{
			slot.setOpacity(OPACITY_HIDDEN);
			hiddenSlots.add(slot);
		}
		else if (!config.hideOriginal() && slot != null && hiddenSlots.remove(slot))
		{
			slot.setOpacity(OPACITY_VISIBLE);
		}

		final int quantity = widgetItem.getQuantity();
		final BufferedImage image = itemManager.getImage(target, quantity, quantity > 1);
		if (image != null)
		{
			graphics.drawImage(image, bounds.x, bounds.y, null);
		}

		if (config.outlineModified())
		{
			final BufferedImage outline = itemManager.getItemOutline(target, quantity, config.outlineColor());
			if (outline != null)
			{
				graphics.drawImage(outline, bounds.x, bounds.y, null);
			}
		}
	}

	void restoreHiddenSlots()
	{
		for (Widget slot : hiddenSlots)
		{
			slot.setOpacity(OPACITY_VISIBLE);
		}
		hiddenSlots.clear();
	}
}
